
const initial={companies:[{id:'show',name:'Show de Bola',icon:'fa-building',segment:'Arena esportiva e lazer',audience:'Jovens e adultos que praticam esportes de areia',voice:'Descontraído, energético e próximo',services:'Beach tennis, vôlei de areia, locação de quadras',differentials:'Ambiente de convivência e prática esportiva',lines:'Humor, Educacional, Vendas, Bastidores',frequency:'3 feed, 2 reels e 5 stories por semana',goal:'Aumentar reservas e fortalecer comunidade',notes:'Não inventar preços, promoções ou horários.'},{id:'dent',name:'Dentsoft Odontoshop',icon:'fa-building',segment:'Loja de produtos odontológicos',audience:'Dentistas, clínicas e estudantes de odontologia',voice:'Profissional, claro e comercial',services:'Materiais e equipamentos odontológicos',differentials:'Variedade de produtos para profissionais',lines:'Educacional, Vendas, Produto, Institucional',frequency:'4 posts e 3 stories por semana',goal:'Gerar interesse em produtos e pedidos',notes:'Não inventar valores, marcas ou condições comerciais.'},{id:'sabor',name:'Sabor da Vila',icon:'fa-building',segment:'Restaurante (fictício)',audience:'Famílias e pessoas que buscam boa gastronomia',voice:'Acolhedor, saboroso e convidativo',services:'Almoço, pratos e refeições',differentials:'Comida caseira e atendimento acolhedor',lines:'Vendas, Bastidores, Humor, Relacionamento',frequency:'3 posts e 7 stories por semana',goal:'Atrair clientes e estimular visitas',notes:'Empresa fictícia para demonstração.'}],ideas:[{id:'i1',title:'5 erros que você deve evitar ao [AÇÃO]',format:'Carrossel',line:'Educacional',goal:'Autoridade',script:'Slide 1: gancho com erro comum. Slides 2 a 6: cinco erros com soluções. Slide 7: CTA para salvar.'},{id:'i2',title:'POV: quando [SITUAÇÃO DO CLIENTE]',format:'Reel',line:'Humor',goal:'Alcance',script:'Gancho visual engraçado. Cena 1: expectativa. Cena 2: realidade. Cena 3: reação e encerramento.'},{id:'i3',title:'3 motivos para escolher [SERVIÇO]',format:'Reel',line:'Vendas',goal:'Conversão',script:'Gancho: Você ainda não conhece? Cenas 1 a 3: benefícios reais. Encerramento: CTA comercial.'},{id:'i4',title:'Um dia nos bastidores da [EMPRESA]',format:'Stories',line:'Bastidores',goal:'Relacionamento',script:'Story 1: abertura. Story 2: rotina. Story 3: detalhe do processo. Story 4: interação.'},{id:'i5',title:'O que ninguém te conta sobre [TEMA]',format:'Carrossel',line:'Educacional',goal:'Engajamento',script:'Slide 1: quebra de expectativa. Slides seguintes: esclarecimentos e exemplos. CTA final.'},{id:'i6',title:'Antes e depois de [PROCESSO]',format:'Post',line:'Institucional',goal:'Autoridade',script:'Mostrar transformação real com contexto e autorização; não inventar resultados.'},{id:'i7',title:'Campanha de Dia das Crianças',format:'Campanha',line:'Sazonal',goal:'Relacionamento',script:'Conceito de campanha sazonal adaptado à empresa, com peça principal e stories de apoio.'},{id:'i8',title:'Qual você escolheria? [OPÇÃO A] ou [OPÇÃO B]',format:'Stories',line:'Interação',goal:'Engajamento',script:'Story 1: enquete. Story 2: mostrar opções. Story 3: convite para responder.'}],posts:[{id:'p1',company:'show',idea:'i1',date:'2026-10-05',time:'18:00',status:'Planejado',title:'5 erros que você deve evitar ao [AÇÃO]',script:'Slide 1: gancho com erro comum. Slides 2 a 6: cinco erros com soluções. Slide 7: CTA para salvar.',caption:''},{id:'p2',company:'show',idea:'i2',date:'2026-10-09',time:'12:00',status:'Em edição',title:'POV: quando [SITUAÇÃO DO CLIENTE]',script:'Gancho visual engraçado. Cena 1: expectativa. Cena 2: realidade. Cena 3: reação.',caption:''},{id:'p3',company:'show',idea:'i7',date:'2026-10-12',time:'09:00',status:'Planejado',title:'Campanha de Dia das Crianças',script:'Campanha sazonal adaptada à marca.',caption:''},{id:'p4',company:'dent',idea:'i3',date:'2026-10-07',time:'19:00',status:'Agendado',title:'3 motivos para escolher [SERVIÇO]',script:'Mostrar três benefícios reais do produto.',caption:''},{id:'p5',company:'dent',idea:'i5',date:'2026-10-15',time:'18:00',status:'Publicado',title:'O que ninguém te conta sobre [TEMA]',script:'Carrossel de informação e educação.',caption:''},{id:'p6',company:'sabor',idea:'i4',date:'2026-10-21',time:'11:00',status:'Planejado',title:'Um dia nos bastidores da [EMPRESA]',script:'Sequência de stories com rotina real.',caption:''}],tasks:[{id:'t1',title:'Gravar Reels da Show de Bola',company:'show',status:'A fazer',date:'2026-10-19'},{id:'t2',title:'Editar carrossel da Dentsoft',company:'dent',status:'Em andamento',date:'2026-10-17'},{id:'t3',title:'Revisar legenda da campanha',company:'show',status:'Revisão',date:'2026-10-18'},{id:'t4',title:'Organizar fotos do restaurante',company:'sabor',status:'Concluído',date:'2026-10-16'}],captures:[{id:'c1',company:'show',date:'2026-10-20',time:'09:00',title:'Captação de Reels na arena'},{id:'c2',company:'dent',date:'2026-10-23',time:'14:00',title:'Fotos de produtos e demonstrações'}]};
const clone=x=>JSON.parse(JSON.stringify(x));let db;try{db=JSON.parse(localStorage.getItem('socialos-demo'))||clone(initial)}catch(e){db=clone(initial)};let page='overview',selectedCompany='show',month='2026-10',lineFilter='Todas';function save(){try{localStorage.setItem('socialos-demo',JSON.stringify(db))}catch(e){console.warn('Armazenamento indisponível:',e)}}function el(s){return document.getElementById(s)}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function company(id){return db.companies.find(x=>x.id===id)||{name:'Empresa não encontrada',icon:'fa-building'}}function idea(id){return db.ideas.find(x=>x.id===id)||{format:'Post',line:'Universal'}}function openModal(t,b){el('modalTitle').textContent=t;el('modalBody').innerHTML=b;el('modal').classList.remove('hidden')}function closeModal(){el('modal').classList.add('hidden')}function toast(t){alert(t)}function resetDemo(){if(confirm('Restaurar os dados de demonstração?')){db=clone(initial);save();render()}}function navigate(p){page=p;render()};const pages=[['overview','◈ Visão geral'],['companies','▦ Empresas'],['ideas',' Banco criativo'],['calendar','▦ Calendário editorial'],['tasks',' Tarefas / Kanban'],['captures','◉ Captações'],['publish','↗ Publicações'],['dates',' Datas especiais'],['reports','▤ Relatórios']];function render(){el('nav').innerHTML=pages.map(([p,t])=>`<button class="${page===p?'active':''}" onclick="navigate('${p}')">${t}</button>`).join('');let names={overview:['Visão geral','Acompanhe o ritmo da sua operação criativa.'],companies:['Empresas','Conhecimento estratégico de cada marca.'],ideas:['Banco criativo','Ideias universais reutilizáveis e prontas para adaptar.'],calendar:['Calendário editorial','Planeje, personalize e exporte o mês.'],tasks:['Produção e tarefas','Organize o fluxo de trabalho da agência.'],captures:['Agenda de captações','Planeje as gravações e sessões de fotos.'],publish:['Publicações','Controle de status e alertas de postagem.'],dates:['Datas especiais','Oportunidades para campanhas criativas.'],reports:['Relatórios mensais','Prestação de contas por cliente, com histórico de entregas.']};el('pageTitle').textContent=names[page][0];el('pageSub').textContent=names[page][1];el('view').innerHTML=({overview:overview,companies:companies,ideas:ideasView,calendar:calendarView,tasks:tasksView,captures:capturesView,publish:publishView,dates:datesView,reports:reportsView})[page]()}function overview(){let pending=db.posts.filter(x=>x.status!=='Publicado').length;return `<div class="tagline"><div class="eyebrow">SEU ESTÚDIO DE IDEIAS</div><h1>Menos caos. Mais criação. </h1><div>Empresas, estratégia, conteúdo e produção em um único fluxo.</div><p><button class="btn primary" onclick="navigate('calendar')">Abrir planejamento →</button></p></div><div class="grid section">${[['','Empresas',db.companies.length],['','Ideias no banco',db.ideas.length],['▦','Publicações pendentes',pending],['','Tarefas abertas',db.tasks.filter(x=>x.status!=='Concluído').length]].map(x=>`<div class="card"><div class="muted">${x[0]} ${x[1]}</div><div class="metric">${x[2]}</div><small>Dados do painel</small></div>`).join('')}</div><div class="two section"><div class="card"><h2>Próximos conteúdos</h2><div class="list">${db.posts.slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(0,6).map(p=>`<div class="item"><div class="row between"><strong>${esc(p.title)}</strong><span class="pill">${esc(p.status)}</span></div><small>${esc(company(p.company).name)} • ${esc(p.date)} às ${esc(p.time)}</small></div>`).join('')}</div></div><div class="card"><h2>Radar da produção</h2>${['A fazer','Em andamento','Revisão','Concluído'].map(s=>`<div style="margin:16px 0"><div class="row between"><span>${s}</span><b>${db.tasks.filter(t=>t.status===s).length}</b></div><div class="progress"><span style="width:${db.tasks.length?db.tasks.filter(t=>t.status===s).length/db.tasks.length*100:0}%"></span></div></div>`).join('')}<div class="notice"> Dica: monte o calendário com ideias universais, exporte o JSON e personalize com o ChatGPT.</div></div></div>`}function companies(){return `<div class="toolbar"><button class="btn primary" onclick="editCompany()">＋ Nova empresa</button><span class="muted">${db.companies.length} clientes cadastrados</span></div><div class="content-grid">${db.companies.map(c=>`<div class="card company"><div class="row"><div class="company-icon"><i class="fa-solid fa-building"></i></div><div><h3>${esc(c.name)}</h3><small>${esc(c.segment)}</small></div></div><div class="muted">${esc(c.audience)}</div><div><span class="pill">${esc(c.lines)}</span></div><div class="row"><button class="btn" onclick="showCompany('${c.id}')">Ver ficha</button><button class="btn" onclick="copyCompany('${c.id}')">⧉ Copiar dados</button><button class="btn" onclick="editCompany('${c.id}')">Editar</button><button class="btn max-danger" onclick="deleteCompany('${c.id}')"><i class="fa-solid fa-trash"></i> Apagar</button></div><div class="report-action"><button class="btn primary" onclick="openReport('${c.id}')">↗ Relatório do mês</button></div></div>`).join('')}</div>`}function companyText(c){return `FICHA ESTRATÉGICA — ${c.name}\nSegmento: ${c.segment}\nPúblico-alvo: ${c.audience}\nTom de voz: ${c.voice}\nProdutos e serviços: ${c.services}\nDiferenciais: ${c.differentials}\nLinhas editoriais: ${c.lines}\nFrequência: ${c.frequency}\nObjetivo: ${c.goal}\nObservações: ${c.notes}\n\nUse estas informações para contextualizar conteúdos sem inventar fatos.`}async function copyText(t){try{await navigator.clipboard.writeText(t);toast('Dados copiados!')}catch(e){openModal('Copie os dados',`<textarea rows="14">${esc(t)}</textarea>`)}}function copyCompany(id){copyText(companyText(company(id)))}function showCompany(id){let c=company(id);openModal(c.name,`<div class="list">${[['Segmento',c.segment],['Público',c.audience],['Tom de voz',c.voice],['Serviços',c.services],['Diferenciais',c.differentials],['Linhas editoriais',c.lines],['Frequência',c.frequency],['Objetivo',c.goal],['Observações',c.notes]].map(([k,v])=>`<div class="item"><small>${k}</small><div>${esc(v)}</div></div>`).join('')}</div><p class="row"><button class="btn primary" onclick="copyCompany('${id}')">⧉ Copiar ficha completa</button><button class="btn" onclick="editCompany('${id}')">Editar dados</button><button class="btn primary" onclick="openReport('${id}')">Relatório mensal</button></p>`)}const MAX_EDITORIAL_TABS=['HUMOR','EDUCACIONAL','VENDAS','BASTIDORES','INSTITUCIONAL','RELACIONAMENTO','INTERACAO','PRODUTO','SAZONAL','UNIVERSAL'];
function maxWeeklyCounts(c){const f=String(c.frequency||'');const match=(words)=>{for(const word of words){const m=f.match(new RegExp('(\\d+)\\s*(?:\\w+\\s*)?'+word,'i'));if(m)return +m[1]}return 0};return {reels:Number.isFinite(+c.weeklyReels)&&c.weeklyReels!==undefined?+c.weeklyReels:match(['reels?']),posts:Number.isFinite(+c.weeklyPosts)&&c.weeklyPosts!==undefined?+c.weeklyPosts:match(['posts?','feed']),stories:Number.isFinite(+c.weeklyStories)&&c.weeklyStories!==undefined?+c.weeklyStories:match(['stor(?:y|ies)'])}}
function editCompany(id){
 const c=id?company(id):{name:'',icon:'fa-building',segment:'',audience:'',voice:'',services:'',differentials:'',lines:'',frequency:'',goal:'',notes:''};
 const selected=String(c.lines||'').split(/[,;]+/).map(x=>x.trim().toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace('Ç','C'));
 const freq=maxWeeklyCounts(c);
 const fields=[['name','Nome da empresa'],['segment','Segmento'],['audience','Público-alvo'],['voice','Tom de voz'],['services','Produtos e serviços'],['differentials','Diferenciais'],['goal','Objetivos'],['notes','Informações adicionais']];
 openModal(id?'Editar empresa':'Nova empresa',`<form id="companyForm">${fields.map(([key,label])=>`<div class="field"><label>${label}</label>${['services','differentials','notes'].includes(key)?`<textarea name="${key}">${esc(c[key])}</textarea>`:`<input name="${key}" value="${esc(c[key])}" ${key==='name'?'required':''}>`}</div>`).join('')}
 <div class="field"><label style="font-weight:800;font-size:14px">Linhas editoriais da empresa</label><small>Selecione as abas da planilha que esta empresa poderá utilizar.</small><div class="max-editorial-choices">${MAX_EDITORIAL_TABS.map(line=>`<label class="max-editorial-option"><input type="checkbox" name="editorial" value="${line}" ${selected.includes(line)?'checked':''}><span>${line==='INTERACAO'?'INTERAÇÃO':line}</span></label>`).join('')}</div></div>
 <div class="field"><label style="font-weight:800;font-size:14px">Frequência semanal de conteúdos</label><small>Defina quantos conteúdos produzir por semana em cada formato.</small><div class="max-frequency-grid"><label>Reels por semana<input type="number" name="weeklyReels" min="0" max="100" step="1" value="${freq.reels}" required></label><label>Posts por semana<input type="number" name="weeklyPosts" min="0" max="100" step="1" value="${freq.posts}" required></label><label>Stories por semana<input type="number" name="weeklyStories" min="0" max="100" step="1" value="${freq.stories}" required></label></div></div>
 <button class="btn primary" type="submit">Salvar empresa</button></form>`);
 el('companyForm').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;const data=Object.fromEntries(new FormData(form));const chosen=Array.from(form.querySelectorAll('input[name="editorial"]:checked')).map(x=>x.value);if(!chosen.length){alert('Selecione pelo menos uma linha editorial.');return}const reels=Number(data.weeklyReels),posts=Number(data.weeklyPosts),stories=Number(data.weeklyStories);delete data.editorial;data.lines=chosen.join(', ');data.weeklyReels=reels;data.weeklyPosts=posts;data.weeklyStories=stories;data.frequency=`${reels} Reels, ${posts} Posts e ${stories} Stories por semana`;if(id)Object.assign(c,data);else db.companies.push({id:'c'+Date.now(),icon:'fa-building',...data});save();closeModal();render()};
}
function ideasView(){let ls=['Todas',...new Set(db.ideas.map(x=>x.line))];return `<div class="toolbar"><input class="search" placeholder="Buscar tema, formato ou objetivo..." id="ideaSearch" oninput="filterIdeas()"><select id="lineFilter" onchange="lineFilter=this.value;filterIdeas()">${ls.map(x=>`<option ${lineFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button class="btn primary" onclick="editIdea()">＋ Nova ideia universal</button></div><div id="ideasGrid" class="content-grid"></div>`}function filterIdeas(){let q=(el('ideaSearch')?.value||'').toLowerCase();el('ideasGrid').innerHTML=db.ideas.filter(i=>(lineFilter==='Todas'||i.line===lineFilter)&&[i.title,i.format,i.goal].join(' ').toLowerCase().includes(q)).map(i=>`<div class="card"><div class="row"><span class="pill">${esc(i.line)}</span><span class="pill mint">${esc(i.format)}</span></div><h3>${esc(i.title)}</h3><div class="muted">Objetivo: ${esc(i.goal)}</div><small>${esc(i.script)}</small><div class="row"><button class="btn" onclick="showIdea('${i.id}')">Ver roteiro</button><button class="btn primary" onclick="addIdeaModal('${i.id}')">＋ Planejar</button></div></div>`).join('')||'<div class="muted">Nenhuma ideia encontrada.</div>'}function showIdea(id){let i=idea(id);openModal(i.title,`<p><span class="pill">${esc(i.format)}</span> <span class="pill">${esc(i.line)}</span></p><p><b>Objetivo:</b> ${esc(i.goal)}</p><div class="item">${esc(i.script)}</div><p><button class="btn primary" onclick="addIdeaModal('${id}')">Adicionar ao calendário</button> <button class="btn" onclick="editIdea('${id}')">Editar ideia universal</button></p>`)}function editIdea(id){let i=id?idea(id):{title:'',format:'Reel',line:'Educacional',goal:'Engajamento',script:''};openModal(id?'Editar ideia':'Nova ideia universal',`<form id="ideaForm">${[['title','Título universal'],['format','Formato'],['line','Linha editorial'],['goal','Objetivo']].map(([k,l])=>`<div class="field"><label>${l}</label><input name="${k}" value="${esc(i[k])}" required></div>`).join('')}<div class="field"><label>Roteiro universal</label><textarea name="script">${esc(i.script)}</textarea></div><button class="btn primary">Salvar ideia</button></form>`);el('ideaForm').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));if(id)Object.assign(i,data);else db.ideas.push({id:'i'+Date.now(),...data});save();closeModal();render()}}function calendarView(){let [year,mo]=month.split('-').map(Number);let first=new Date(year,mo-1,1).getDay(),total=new Date(year,mo,0).getDate(),posts=db.posts.filter(p=>p.company===selectedCompany&&p.date.startsWith(month));let caps=db.captures.filter(c=>c.company===selectedCompany&&c.date.startsWith(month));let cells=Array.from({length:first},()=>'<div class="day blank"></div>');for(let d=1;d<=total;d++){let date=`${month}-${String(d).padStart(2,'0')}`;cells.push(`<div class="day"><div class="row between"><span class="daynum">${d}</span><button style="background:none;color:var(--mint)" onclick="addIdeaModal(null,'${date}')">＋</button></div>${posts.filter(p=>p.date===date).map(p=>`<button class="event" onclick="editPost('${p.id}')">${esc(p.time)} ${esc(p.title)}</button>`).join('')}${caps.filter(c=>c.date===date).map(c=>`<button class="event capture" onclick="showCapture('${c.id}')"> ${esc(c.title)}</button>`).join('')}</div>`)}return `<div class="toolbar"><select onchange="selectedCompany=this.value;render()">${db.companies.map(c=>`<option value="${c.id}" ${selectedCompany===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><input type="month" value="${month}" onchange="month=this.value;render()"><button class="btn primary" onclick="addIdeaModal()">＋ Adicionar conteúdo</button><button class="btn" onclick="captureModal()"> Agendar captação</button></div><div class="toolbar"><button class="btn green" onclick="downloadEditorial()">↓ Baixar arquivo editorial (.json)</button><button class="btn" onclick="el('editorialUpload').click()">↑ Fazer upload editorial (.json)</button><input class="hidden" type="file" id="editorialUpload" accept=".json,application/json" onchange="uploadEditorial(event)"><button class="btn" onclick="downloadClient()">↓ Versão cliente (.html)</button></div><div class="notice" style="margin-bottom:15px">Fluxo com IA: exporte o JSON, personalize no ChatGPT e importe o arquivo devolvido. O sistema preserva datas e horários.</div><div class="card"><div class="row between"><h2>${new Date(year,mo-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})} — ${esc(company(selectedCompany).name)}</h2><span class="pill mint">${posts.length} conteúdos</span></div><div class="calendar">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells.join('')}</div></div><div class="section card"><h2>Conteúdos do mês</h2><div class="list">${posts.length?posts.map(p=>`<div class="item"><div class="row between"><div><strong>${esc(p.title)}</strong><small>${esc(p.date)} • ${esc(p.time)} • ${esc(idea(p.idea).format)}</small></div><div class="row"><span class="pill">${esc(p.status)}</span><button class="btn" onclick="editPost('${p.id}')">Abrir roteiro</button></div></div></div>`).join(''):'<div class="muted">Nenhum conteúdo. Adicione uma ideia universal para começar.</div>'}</div></div>`}function addIdeaModal(id,date){openModal('Adicionar ao calendário',`<form id="addPostForm"><div class="field"><label>Empresa</label><select name="company">${db.companies.map(c=>`<option value="${c.id}" ${selectedCompany===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Conteúdo universal</label><select name="idea">${db.ideas.map(i=>`<option value="${i.id}" ${id===i.id?'selected':''}>${esc(i.title)} — ${esc(i.format)}</option>`).join('')}</select></div><div class="field"><label>Data</label><input name="date" type="date" required value="${date||month+'-05'}"></div><div class="field"><label>Horário</label><input name="time" type="time" value="18:00"></div><button class="btn primary">Adicionar conteúdo</button></form>`);el('addPostForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),i=idea(f.idea);db.posts.push({id:'p'+Date.now(),...f,status:'Planejado',title:i.title,script:i.script,caption:''});selectedCompany=f.company;month=f.date.slice(0,7);save();closeModal();navigate('calendar')}}function editPost(id){let p=db.posts.find(x=>x.id===id);openModal('Editar conteúdo',`<form id="postForm"><div class="field"><label>Tema escolhido</label><input name="theme" value="${esc(p.theme||'')}" placeholder="Tema central desta publicação"></div><div class="field"><label>Título</label><input name="title" value="${esc(p.title)}"></div><div class="field"><label>Roteiro</label><textarea name="script" style="min-height:150px">${esc(p.script)}</textarea></div><div class="field"><label>Legenda</label><textarea name="caption">${esc(p.caption)}</textarea></div><div class="row"><div class="field"><label>Data</label><input type="date" name="date" value="${p.date}"></div><div class="field"><label>Hora</label><input type="time" name="time" value="${p.time}"></div></div><div class="field"><label>Status</label><select name="status">${['Planejado','Em edição','Em revisão','Agendado','Publicado'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select></div><button class="btn primary">Salvar alterações</button> <button type="button" class="btn" onclick="deletePost('${id}')">Excluir</button></form>`);el('postForm').onsubmit=e=>{e.preventDefault();Object.assign(p,Object.fromEntries(new FormData(e.target)));save();closeModal();render()}}function deletePost(id){if(confirm('Excluir conteúdo?')){db.posts=db.posts.filter(p=>p.id!==id);save();closeModal();render()}}function editorialObject(){let c=company(selectedCompany);return {schema_version:'1.0',file_type:'socialos_editorial',company_id:selectedCompany,period:month,company_profile:clone(c),ai_instructions:'Você é estrategista de social media. Personalize títulos, roteiros e crie uma LEGENDA SUGERIDA COMPLETA para TODOS os conteúdos com base nos dados da empresa, no formato e na linha editorial. Não invente preços, promoções, serviços ou fatos. Use obrigatoriamente o campo theme (tema específico escolhido na agenda) como eixo central de cada conteúdo. Personalize o título, o gancho, as falas, as cenas e escreva no campo caption uma legenda pronta para publicação, natural, envolvente, adequada ao tom de voz da empresa, com CTA pertinente e hashtags relevantes (sem inventar informações), para esse tema e para a empresa; não se limite a substituir palavras. Em Reels, organize NOME DO REELS, CONTEÚDO, GANCHO, FALA INICIAL, FALAS 01/02/03 e encerramento com duração máxima de 40 segundos e técnica de yapping e/ou storytelling adequada à linha editorial. Para Stories, use sequência de telas e interações; para Post, título, subtexto, direção criativa, legenda e CTA. Preserve exatamente schema_version, file_type, company_id, period, ids, idea_id, dates, times, format, editorial_line, theme e status. Edite somente title, script e caption. Não remova nem adicione itens. Devolva um arquivo JSON válido, sem markdown, com a mesma estrutura.',contents:db.posts.filter(p=>p.company===selectedCompany&&p.date.startsWith(month)).map(p=>({id:p.id,idea_id:p.idea,date:p.date,time:p.time,format:idea(p.idea).format,editorial_line:idea(p.idea).line,theme:p.theme||'',status:p.status,title:p.title,script:p.script,caption:p.caption||''}))}}function download(name,content,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}function downloadEditorial(){download(`editorial_${selectedCompany}_${month}.json`,JSON.stringify(editorialObject(),null,2),'application/json')}async function uploadEditorial(e){let file=e.target.files[0];if(!file)return;try{let obj=JSON.parse(await file.text());if(obj.file_type!=='socialos_editorial'||obj.company_id!==selectedCompany||obj.period!==month||!Array.isArray(obj.contents))throw Error('Arquivo incompatível com esta empresa ou mês.');let current=db.posts.filter(p=>p.company===selectedCompany&&p.date.startsWith(month));if(obj.contents.length!==current.length||new Set(obj.contents.map(x=>x.id)).size!==current.length)throw Error('A lista de conteúdos foi alterada.');for(let item of obj.contents){let p=current.find(x=>x.id===item.id);if(!p||item.idea_id!==p.idea||item.date!==p.date||item.time!==p.time||item.format!==idea(p.idea).format||item.editorial_line!==idea(p.idea).line||item.theme!==(p.theme||'')||item.status!==p.status||!['title','script','caption'].every(k=>typeof item[k]==='string'))throw Error('IDs, datas, formatos ou campos incompatíveis.')}openModal('Conferir importação',`<div class="notice">${current.length} conteúdos identificados. Serão atualizados somente títulos, roteiros e legendas. Temas, datas, horários e status serão preservados.</div><p>Deseja aplicar as alterações?</p><button class="btn green" id="applyUpload">Aplicar personalização</button>`);el('applyUpload').onclick=()=>{for(let item of obj.contents){let p=current.find(x=>x.id===item.id);p.title=item.title;p.script=item.script;p.caption=item.caption}save();closeModal();render();toast('Conteúdos personalizados com sucesso!')}}catch(err){toast('Não foi possível importar: '+err.message)}finally{e.target.value=''}}function downloadClient(){let c=company(selectedCompany),p=db.posts.filter(x=>x.company===selectedCompany&&x.date.startsWith(month)).sort((a,b)=>a.date.localeCompare(b.date));let html=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Planejamento — ${esc(c.name)}</title><style>body{font:16px system-ui;max-width:950px;margin:40px auto;padding:20px;color:#172039;background:#f7f9fc}h1{font-size:32px}.entry{background:white;padding:22px;margin:15px 0;border-radius:15px;box-shadow:0 4px 20px #14213d12}small{color:#69748b}pre{white-space:pre-wrap;font:inherit}</style><h1>Planejamento Editorial</h1><p>${esc(c.name)} • ${esc(month)}</p>${p.map(x=>`<article class="entry"><small>${esc(x.date)} às ${esc(x.time)} • ${esc(idea(x.idea).format)}</small><h2>${esc(x.title)}</h2><h3>Roteiro</h3><pre>${esc(x.script)}</pre><h3>Legenda</h3><pre>${esc(x.caption||'A definir')}</pre></article>`).join('')}</html>`;download(`cliente_${selectedCompany}_${month}.html`,html,'text/html')}function maxDeleteRecord(collection,id){const labels={tasks:'tarefa',captures:'captação',agenda:'compromisso'};if(!['tasks','captures','agenda'].includes(collection))return;const record=(db[collection]||[]).find(x=>String(x.id)===String(id));if(!record)return;if(!confirm('Excluir '+labels[collection]+' "'+(record.title||'')+'"? A exclusão também será enviada ao Google Sheets.'))return;db[collection]=db[collection].filter(x=>String(x.id)!==String(id));save();closeModal();render()}
function tasksView(){return `<div class="toolbar"><button class="btn primary" onclick="taskModal()">＋ Nova tarefa</button></div><div class="kanban">${['A fazer','Em andamento','Revisão','Concluído'].map(s=>`<div class="card"><div class="row between"><h3>${s}</h3><span class="pill">${db.tasks.filter(t=>t.status===s).length}</span></div>${db.tasks.filter(t=>t.status===s).map(t=>`<div class="item"><strong>${esc(t.title)}</strong><small>${esc(company(t.company).name)} • ${esc(t.date)}</small><p><button class="btn" onclick="taskModal('${t.id}')">Editar / mover</button> <button class="btn" onclick="maxDeleteRecord('tasks','${t.id}')">Excluir</button></p></div>`).join('')}</div>`).join('')}</div>`}function taskModal(id){let t=id?db.tasks.find(x=>x.id===id):{title:'',company:selectedCompany,status:'A fazer',date:'2026-10-20'};openModal(id?'Editar tarefa':'Nova tarefa',`<form id="taskForm"><div class="field"><label>Tarefa</label><input required name="title" value="${esc(t.title)}"></div><div class="field"><label>Empresa</label><select name="company">${db.companies.map(c=>`<option value="${c.id}" ${t.company===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Prazo</label><input name="date" type="date" value="${t.date}"></div><div class="field"><label>Etapa</label><select name="status">${['A fazer','Em andamento','Revisão','Concluído'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></div><button class="btn primary">Salvar tarefa</button>${id?`<button class="btn" type="button" onclick="maxDeleteRecord('tasks','${id}')">Excluir tarefa</button>`:''}</form>`);el('taskForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(id)Object.assign(t,f);else db.tasks.push({id:'t'+Date.now(),...f});save();closeModal();render()}}function capturesView(){return `<div class="toolbar"><button class="btn primary" onclick="captureModal()">＋ Agendar captação</button></div><div class="three">${db.captures.map(c=>`<div class="card"><div class="eyebrow"> CAPTAÇÃO</div><h3 style="margin-top:12px">${esc(c.title)}</h3><p>${esc(company(c.company).name)}</p><span class="pill mint">${esc(c.date)} • ${esc(c.time)}</span><p><button class="btn" onclick="showCapture('${c.id}')">Ver / editar</button> <button class="btn" onclick="maxDeleteRecord('captures','${c.id}')">Excluir</button></p></div>`).join('')}</div>`}function showCapture(id){captureModal(id)}function captureModal(id){let c=id?db.captures.find(x=>x.id===id):{title:'',company:selectedCompany,date:month+'-20',time:'09:00'};openModal(id?'Editar captação':'Agendar captação',`<form id="captureForm"><div class="field"><label>Nome da captação</label><input name="title" required value="${esc(c.title)}"></div><div class="field"><label>Empresa</label><select name="company">${db.companies.map(x=>`<option value="${x.id}" ${c.company===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Data</label><input type="date" name="date" value="${c.date}"></div><div class="field"><label>Horário</label><input type="time" name="time" value="${c.time}"></div><button class="btn primary">Salvar captação</button>${id?`<button class="btn" type="button" onclick="maxDeleteRecord('captures','${id}')">Excluir captação</button>`:''}</form>`);el('captureForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(id)Object.assign(c,f);else db.captures.push({id:'c'+Date.now(),...f});save();closeModal();render()}}function publishView(){return `<div class="notice">As publicações são gerenciadas aqui por status. Envio de e-mails e publicação automática exigem backend e integrações reais.</div><div class="card section"><h2>Fila de publicações</h2><div class="list">${db.posts.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(p=>`<div class="item"><div class="row between"><div><strong>${esc(p.title)}</strong><small>${esc(company(p.company).name)} • ${esc(p.date)} às ${esc(p.time)}</small></div><div class="row"><span class="pill">${esc(p.status)}</span><button class="btn" onclick="editPost('${p.id}')">Editar / status</button></div></div></div>`).join('')}</div></div>`}function datesView(){let dates=[['12/10','Dia das Crianças','Campanha afetiva, atividades em família, experiência e interação'],['15/10','Dia dos Professores','Homenagem e valorização de profissionais'],['31/10','Halloween','Conteúdo criativo, humor e temática visual'],['25/12','Natal','Campanhas de relacionamento e vendas'],['01/01','Ano Novo','Metas, retrospectiva e recomeços']];return `<div class="notice">Sugestões ilustrativas de campanhas. Verifique pertinência ao segmento e condições reais da empresa.</div><div class="content-grid section">${dates.map(d=>`<div class="card"><span class="pill orange">${d[0]}</span><h3>${d[1]}</h3><p class="muted">${d[2]}</p><button class="btn" onclick="addIdeaModal('i7')">Planejar campanha →</button></div>`).join('')}</div>`}
// Novo fluxo de seleção editorial por formato, linha e prévia de roteiro.
let libraryFormat='Reel',libraryLine='Todas',libraryQuery='',previewIdea=null,libraryDate='';
const extraIdeas=[
{id:'r9',format:'Reel',line:'Humor',goal:'Alcance',title:'O cliente que diz "só vou olhar" [SITUAÇÃO]',script:'NOME DO REELS: O cliente que só ia olhar\nCONTEÚDO: Meme encenado com contraste entre intenção e realidade.\nGANCHO (0–3s): Câmera aproxima rapidamente e texto: “Eu só vim dar uma olhadinha...”\nFALA INICIAL (3–7s): “Foi isso que eu disse antes de conhecer [SERVIÇO/PRODUTO].”\nCENA 01 (7–15s): Mostre a promessa de não comprar/participar, com corte seco.\nFALA 02 (15–23s): “Aí me mostraram [BENEFÍCIO REAL]...”\nCENA 03 (23–32s): Reação exagerada e humor visual, com legenda curta.\nENCERRAMENTO (32–38s): “Quem é assim? Marca a pessoa!”\nTÉCNICA: Yapping acelerado, cortes de 2–4 segundos e quebra de expectativa.'},
{id:'r10',format:'Reel',line:'Educacional',goal:'Salvamentos',title:'3 coisas que ninguém explica sobre [TEMA]',script:'NOME DO REELS: Ninguém te explicou isso\nCONTEÚDO: Mini-aula prática em storytelling com demonstração.\nGANCHO (0–3s): “Se você faz [AÇÃO], precisa saber disso!”\nFALA INICIAL (3–8s): “Eu vejo esse erro toda semana e ele é fácil de evitar.”\nFALA 01 (8–17s): “Primeiro: [DICA REAL 1].” Mostre um exemplo.\nFALA 02 (17–26s): “Segundo: [DICA REAL 2].” Corte para outro enquadramento.\nFALA 03 (26–34s): “E o terceiro muda tudo: [DICA REAL 3].”\nENCERRAMENTO (34–39s): “Salva para não esquecer!”\nTÉCNICA: Yapping com frases curtas, legendas dinâmicas e progressão de curiosidade.'},
{id:'r11',format:'Reel',line:'Vendas',goal:'Conversão',title:'Antes de escolher [PRODUTO/SERVIÇO], veja isso',script:'NOME DO REELS: Antes de decidir\nCONTEÚDO: História curta de uma decisão de compra.\nGANCHO (0–4s): “O barato pode sair caro quando você ignora isto.”\nFALA INICIAL (4–10s): “Um cliente chegou com uma dúvida comum: [DÚVIDA REAL].”\nFALA 01 (10–19s): “A primeira coisa que mostramos foi [CRITÉRIO 1].”\nFALA 02 (19–28s): “Depois, comparamos [CRITÉRIO 2] sem prometer milagres.”\nFALA 03 (28–35s): “O melhor é escolher o que faz sentido para sua necessidade.”\nENCERRAMENTO (35–40s): “Quer ajuda? Chama nossa equipe.”\nTÉCNICA: Storytelling consultivo, cenas reais e cortes objetivos.'},
{id:'r12',format:'Reel',line:'Bastidores',goal:'Relacionamento',title:'Um problema real e como resolvemos [SITUAÇÃO]',script:'NOME DO REELS: O que acontece por trás\nCONTEÚDO: Storytelling de rotina, sem inventar casos.\nGANCHO (0–3s): “Parece simples, mas olha o que acontece antes...”\nFALA INICIAL (3–9s): “Hoje vamos te mostrar como preparamos [ATIVIDADE REAL].”\nFALA 01 (9–17s): “Tudo começa com [ETAPA 1].”\nFALA 02 (17–25s): “Depois conferimos [ETAPA 2].”\nFALA 03 (25–33s): “É esse cuidado que faz diferença na experiência.”\nENCERRAMENTO (33–39s): “Quer ver mais bastidores? Comenta!”\nTÉCNICA: Storytelling visual, planos de detalhe e cortes rápidos.'},
{id:'r13',format:'Reel',line:'Produto',goal:'Interesse',title:'Teste rápido: [PRODUTO] vale a atenção?',script:'NOME DO REELS: O teste de 30 segundos\nCONTEÚDO: Demonstração honesta de produto.\nGANCHO (0–3s): “Você sabe para que serve isso?”\nFALA INICIAL (3–8s): “Vou mostrar três detalhes do [PRODUTO].”\nFALA 01 (8–17s): “Esse é o principal uso: [USO COMPROVADO].”\nFALA 02 (17–26s): “Observe este detalhe: [CARACTERÍSTICA REAL].”\nFALA 03 (26–34s): “E antes de escolher, confira [ORIENTAÇÃO].”\nENCERRAMENTO (34–39s): “Fale com nossa equipe para saber mais.”\nTÉCNICA: Close-ups, demonstração e yapping explicativo.'},
{id:'r14',format:'Reel',line:'Institucional',goal:'Autoridade',title:'A história por trás de [EMPRESA]',script:'NOME DO REELS: Por que fazemos isso\nCONTEÚDO: História real da marca em primeira pessoa.\nGANCHO (0–4s): “Pouca gente sabe como tudo começou...”\nFALA INICIAL (4–10s): “A [EMPRESA] nasceu quando [FATO VERIFICADO].”\nFALA 01 (10–19s): “Nosso primeiro desafio foi [FATO].”\nFALA 02 (19–28s): “Aprendemos que [VALOR REAL DA MARCA].”\nFALA 03 (28–35s): “Hoje seguimos com o mesmo propósito.”\nENCERRAMENTO (35–40s): “Você já conhecia nossa história?”\nTÉCNICA: Storytelling com imagens de arquivo reais.'},
{id:'r15',format:'Reel',line:'Relacionamento',goal:'Comentários',title:'Qual é o seu tipo de [CLIENTE/PRATICANTE]?',script:'NOME DO REELS: Qual desses é você?\nCONTEÚDO: Identificação com perfis reais do público.\nGANCHO (0–3s): “Todo grupo tem esses três tipos de pessoa!”\nFALA INICIAL (3–8s): “O primeiro é o [PERFIL 1].”\nFALA 01 (8–17s): Encene o perfil 1 com humor leve.\nFALA 02 (17–26s): “O segundo é o [PERFIL 2].” Corte para outro personagem.\nFALA 03 (26–34s): “E tem o [PERFIL 3]!” Mostre reação engraçada.\nENCERRAMENTO (34–39s): “Qual deles é você? Marca o amigo!”\nTÉCNICA: Yapping humorístico, personagens e cortes de ritmo.'},
{id:'s9',format:'Stories',line:'Humor',goal:'Respostas',title:'Enquete meme: quem nunca [SITUAÇÃO]?',script:'STORY 01: Meme ou reação engraçada com pergunta “Quem nunca [SITUAÇÃO]?”\nSTORY 02: Enquete “Eu sempre  / Nunca aconteceu ”.\nSTORY 03: Bastidor ou reação da equipe e caixa “Conta sua história”.'},
{id:'s10',format:'Stories',line:'Educacional',goal:'Interação',title:'Quiz: mito ou verdade sobre [TEMA]?',script:'STORY 01: Gancho com dúvida real sobre [TEMA].\nSTORY 02: Enquete “Mito / Verdade”.\nSTORY 03: Resposta com explicação objetiva e verificável.\nSTORY 04: CTA “Quer mais dicas assim?”'},
{id:'s11',format:'Stories',line:'Vendas',goal:'Conversão',title:'Sequência de apresentação de [SERVIÇO]',script:'STORY 01: Dor ou desejo real do público.\nSTORY 02: Mostrar [SERVIÇO] em ação.\nSTORY 03: Benefício real, sem promessa exagerada.\nSTORY 04: CTA com link ou convite para mensagem.'},
{id:'s12',format:'Stories',line:'Produto',goal:'Interesse',title:'Detalhe do dia: [PRODUTO]',script:'STORY 01: Close do produto com pergunta.\nSTORY 02: Demonstração de característica real.\nSTORY 03: Enquete de interesse.\nSTORY 04: CTA para consultar disponibilidade.'},
{id:'s13',format:'Stories',line:'Relacionamento',goal:'Respostas',title:'Caixinha: você decide o próximo [TEMA]',script:'STORY 01: Contexto com selfie da equipe.\nSTORY 02: Caixa de perguntas “O que você quer ver por aqui?”\nSTORY 03: Resposta a uma sugestão real.'},
{id:'p9',format:'Post',line:'Humor',goal:'Compartilhamentos',title:'Meme: expectativa x realidade de [SITUAÇÃO]',script:'TÍTULO DA ARTE: “Expectativa x realidade”\nIDEIA VISUAL: Duas cenas contrastantes, foto ou montagem autoral.\nTEXTO DA ARTE: Expectativa: [EXPECTATIVA]. Realidade: [REALIDADE].\nLEGENDA: Frase curta, divertida e identificável, seguida de pergunta para gerar comentários.\nCTA: “Marca quem é exatamente assim!”'},
{id:'p10',format:'Post',line:'Educacional',goal:'Salvamentos',title:'Checklist para acertar em [TEMA]',script:'TÍTULO PRINCIPAL: “Checklist de [TEMA]”\nSUBTEXTO: “O que conferir antes de [AÇÃO]”\nCONTEÚDO DA ARTE: 3 a 5 itens verificáveis e simples.\nDIREÇÃO VISUAL: Layout limpo, ícones e destaque para a informação.\nLEGENDA: Explicação curta de cada item.\nCTA: “Salve para consultar depois.”'},
{id:'p11',format:'Post',line:'Vendas',goal:'Conversão',title:'[PRODUTO/SERVIÇO] para sua rotina',script:'TÍTULO PRINCIPAL: “[BENEFÍCIO REAL] começa aqui”\nSUBTEXTO: Apresente o produto/serviço sem inventar condições.\nDIREÇÃO VISUAL: Foto real do produto ou serviço em destaque e espaço para texto.\nLEGENDA: Benefício, contexto de uso e convite para contato.\nCTA: “Fale com a equipe.”'},
{id:'p12',format:'Post',line:'Institucional',goal:'Reconhecimento',title:'O que move a [EMPRESA]',script:'TÍTULO PRINCIPAL: “Mais que [SERVIÇO], um propósito”\nSUBTEXTO: Valor real da marca.\nDIREÇÃO VISUAL: Foto real da equipe ou operação.\nLEGENDA: História ou compromisso verdadeiro da empresa.\nCTA: “Conheça nossa história.”'},
{id:'p13',format:'Post',line:'Produto',goal:'Interesse',title:'Você conhece os detalhes de [PRODUTO]?',script:'TÍTULO PRINCIPAL: “Conheça [PRODUTO]”\nSUBTEXTO: Uma característica objetiva.\nDIREÇÃO VISUAL: Foto real do item, detalhes discretos.\nLEGENDA: Para que serve, público indicado e diferenciais confirmados.\nCTA: “Consulte nossa equipe.”'},
{id:'p14',format:'Post',line:'Bastidores',goal:'Proximidade',title:'Por trás de cada [ENTREGA]',script:'TÍTULO PRINCIPAL: “Tem muito cuidado por trás disso”\nSUBTEXTO: [ETAPA REAL DO PROCESSO]\nDIREÇÃO VISUAL: Foto documental de equipe ou operação.\nLEGENDA: Breve história do processo, sem criar fatos.\nCTA: “Quer ver mais do nosso dia a dia?”'}
];
for(const i of extraIdeas)if(!db.ideas.some(x=>x.id===i.id))db.ideas.push(i);
save();
// Normalização centralizada: compatibilidade entre cadastros e banco criativo.
function maxEditorialKey(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ').replace(/ç/g,'c').replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,'');}
function maxEditorialLine(value){const k=maxEditorialKey(value);const aliases={interacao:'interacao',interacoes:'interacao',interativo:'interacao',educacao:'educacional',educativo:'educacional',instituicao:'institucional',venda:'vendas',produto:'produto',produtos:'produto',relacionamentos:'relacionamento',bastidor:'bastidores',memes:'humor',meme:'humor',datascomemorativas:'sazonal',datascomemorativa:'sazonal',comemorativas:'sazonal'};return aliases[k]||k;}
function normalizedFormat(f){const k=maxEditorialKey(f);if(['reel','reels','video','videos','video curto','videos curtos'].includes(k))return 'Reel';if(['story','stories','storie','sequencia de stories'].includes(k))return 'Stories';if(['post','posts','feed','post estatico','post estatico feed','carrossel','carrossels','carrosseis','arte','imagem','foto','fotografia','post unico'].includes(k))return 'Post';return null;}
function companyLines(){const raw=company(selectedCompany).lines;return (Array.isArray(raw)?raw:String(raw||'').split(/[,;|\n]+/)).map(x=>String(x).trim()).filter(Boolean);}
function matchingIdeas(){const allowed=new Set(companyLines().map(maxEditorialLine));const selected=maxEditorialLine(libraryLine);const query=maxEditorialKey(libraryQuery);return (db.ideas||[]).filter(i=>{const line=maxEditorialLine(i.line||i.editorial_line||i.linha_editorial);const format=normalizedFormat(i.format||i.formato||i.type);if(format!==libraryFormat)return false;if(libraryLine!=='Todas'&&line!==selected)return false;if(line!=='universal'&&!allowed.has(line))return false;return !query||maxEditorialKey([i.title,i.line,i.goal,i.script].join(' ')).includes(query);});}
function openLibrary(date='',format=''){libraryDate=date;libraryFormat=format||'Reel';libraryLine='Todas';libraryQuery='';previewIdea=null;page='library';render()}
function changeLibraryFormat(f){libraryFormat=f;libraryLine='Todas';previewIdea=null;render()}
function changeLibraryLine(l){libraryLine=l;previewIdea=null;render()}
function searchLibrary(q){libraryQuery=q;updateLibraryCards()}
function updateLibraryCards(){let node=el('libraryCards');if(node)node.innerHTML=libraryCards()}
function libraryCards(){let items=matchingIdeas();return items.map(i=>`<div class="library-card"><div class="row between"><span class="pill mint">${esc(i.line)}</span><span class="pill">${esc(i.goal)}</span></div><h3>${esc(i.title)}</h3><p>${esc(i.script.slice(0,105))}...</p><div class="row"><button class="btn" onclick="previewLibrary('${i.id}')">◉ Ver roteiro</button><button class="btn primary" onclick="planLibraryIdea('${i.id}')">＋ Escolher</button></div></div>`).join('')||'<div class="notice">Ainda não há ideias desse formato e linha editorial para esta empresa. Cadastre novas ideias no Banco Criativo ou altere o filtro.</div>'}
function previewLibrary(id){previewIdea=id;let i=idea(id);el('libraryPreview').innerHTML=`<div class="eyebrow">PRÉVIA COMPLETA · ${esc(i.format)}</div><h2>${esc(i.title)}</h2><p><span class="pill">${esc(i.line)}</span> <span class="pill mint">${esc(i.goal)}</span></p><div class="script-preview">${esc(i.script)}</div><p><button class="btn primary" onclick="planLibraryIdea('${i.id}')">＋ Usar no calendário →</button></p><small>Roteiro universal: a personalização por empresa acontece no Fluxo Editorial com IA.</small>`}
function libraryView(){let lines=companyLines();return `<div class="creator-hero"><div class="eyebrow">ESTÚDIO DE PLANEJAMENTO · ETAPA 02</div><h2>Encontre a ideia certa. Antes de criar, escolha o formato.</h2><p class="muted">Sugestões alinhadas às linhas editoriais de <b>${esc(company(selectedCompany).name)}</b>. Cada formato tem um roteiro próprio.</p><div class="creator-steps"><span class="creator-step"> Empresa definida</span><span class="creator-step">② Formato e linha editorial</span><span class="creator-step">③ Prévia de roteiro</span><span class="creator-step">④ Agendar conteúdo</span></div></div><div class="row between"><h2>01 · Qual conteúdo vamos produzir?</h2><button class="btn" onclick="navigate('calendar')">← Voltar ao calendário</button></div><div class="format-grid">${[['Reel','','Vídeo até 40s · gancho, yapping e storytelling'],['Stories','','Sequência de telas · interação e enquetes'],['Post','▧','Arte estática ou carrossel · título, texto e legenda']].map(([f,ico,desc])=>`<button class="format-tile ${libraryFormat===f?'active':''}" onclick="changeLibraryFormat('${f}')"><span class="format-icon">${ico}</span><b>${f==='Reel'?'Reels':f}</b><p class="muted">${desc}</p></button>`).join('')}</div><h2>02 · Explore as linhas editoriais da marca</h2><div class="filter-chips">${['Todas',...lines].map(l=>`<button class="filter-chip ${libraryLine===l?'active':''}" onclick="changeLibraryLine('${esc(l)}')">${l==='Humor'?' ':l==='Educacional'?' ':l==='Vendas'?' ':l==='Bastidores'?' ':''}${esc(l)}</button>`).join('')}</div><div class="toolbar"><input class="search" style="flex:1" placeholder="Buscar ideia, gancho, objetivo ou tema..." value="${esc(libraryQuery)}" oninput="searchLibrary(this.value)"><span class="library-count">${matchingIdeas().length} ideias disponíveis</span></div><div class="library-layout"><div id="libraryCards" class="library-cards">${libraryCards()}</div><aside class="preview-panel" id="libraryPreview"><div class="eyebrow">PRÉVIA DE ROTEIRO</div><h2>Selecione uma ideia </h2><p class="muted">Clique em “Ver roteiro” para conferir o conteúdo completo antes de adicionar ao calendário.</p><div class="notice"> Reels: nome, conceito, gancho, fala inicial, falas/cenas e encerramento em até 40 segundos.<br><br> Stories: sequência de telas e interações.<br><br>▧ Posts: título, subtexto, direção criativa, legenda e CTA.</div></aside></div>`}
function themeAdapt(text,theme){if(!theme)return text;return String(text).replace(/\[(?:TEMA|AÇÃO|SITUAÇÃO|ATIVIDADE|ASSUNTO)\]/gi,theme)}
function planLibraryIdea(id){let i=idea(id);openModal('Agendar · '+i.title,`<div class="notice"><b>${esc(i.format)} · ${esc(i.line)}</b><br>${esc(i.title)}</div><form id="libraryPlanForm"><div class="field"><label>Tema específico para esta publicação</label><input name="theme" required placeholder="Ex.: erros de iniciantes no beach tennis"></div><div class="notice">O tema escolhido será usado para contextualizar o título e o roteiro inicial e seguirá no prompt editorial para a IA aprofundar a personalização.</div><div class="field"><label>Data da publicação</label><input name="date" type="date" required value="${libraryDate||month+'-20'}"></div><div class="field"><label>Horário</label><input name="time" type="time" required value="18:00"></div><button class="btn primary">Adicionar ao calendário →</button></form>`);el('libraryPlanForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));db.posts.push({id:'p'+Date.now(),company:selectedCompany,idea:id,date:f.date,time:f.time,status:'Planejado',theme:f.theme,title:themeAdapt(i.title,f.theme),script:themeAdapt(i.script,f.theme),caption:''});month=f.date.slice(0,7);save();closeModal();navigate('calendar')}}
addIdeaModal=function(id,date){if(id){let i=idea(id);selectedCompany=selectedCompany||db.companies[0].id;libraryDate=date||'';planLibraryIdea(id)}else openLibrary(date)};
const previousCalendar=calendarView;
calendarView=function(){let html=previousCalendar();html=html.replace(/onclick="addIdeaModal\(null,'([^']+)'\)"/g,`onclick="openLibrary('$1')"`).replace(/onclick="addIdeaModal\(\)"/g,`onclick="openLibrary()"`);let banner=`<div class="creator-hero"><div class="eyebrow">SEU PLANEJAMENTO CRIATIVO</div><h2>Do insight ao calendário. Sem ideias genéricas.</h2><p class="muted">Escolha o formato primeiro, explore apenas as linhas editoriais da empresa, veja o roteiro e defina o dia.</p><button class="btn primary" onclick="openLibrary()"> Explorar conteúdos por formato →</button></div>`;return banner+html};
const renderBase=render;
render=function(){if(page==='library'){el('nav').innerHTML=pages.map(([p,t])=>`<button class="${p==='calendar'?'active':''}" onclick="navigate('${p}')">${t}</button>`).join('');el('pageTitle').textContent='Biblioteca para o calendário';el('pageSub').textContent=company(selectedCompany).name+' · Ideias selecionadas por linha editorial e formato';el('view').innerHTML=libraryView();return}renderBase()};


// Prestação de contas — dados baseados exclusivamente nos registros locais.
let reportCompany='show',reportMonth='2026-10';
function reportData(cid,period){let posts=db.posts.filter(p=>p.company===cid&&p.date.startsWith(period)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));let captures=db.captures.filter(c=>c.company===cid&&c.date.startsWith(period));let tasks=db.tasks.filter(t=>t.company===cid&&t.date.startsWith(period));return {posts,captures,tasks,published:posts.filter(p=>p.status==='Publicado').length,inProgress:posts.filter(p=>['Em edição','Em revisão','Agendado'].includes(p.status)).length,planned:posts.filter(p=>p.status==='Planejado').length};}
function monthLabel(m){return new Date(Number(m.slice(0,4)),Number(m.slice(5,7))-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});}
function openReport(cid){reportCompany=cid;reportMonth=month;page='reports';render();}
function reportsView(){let c=company(reportCompany),d=reportData(reportCompany,reportMonth);return `<div class="report-hero"><div><div class="eyebrow">PRESTAÇÃO DE CONTAS / ${esc(monthLabel(reportMonth).toUpperCase())}</div><h2 style="font-size:25px;margin:8px 0">Relatório de produção editorial</h2><div class="muted">${esc(c.name)} · Registro de conteúdos e atividades do período</div></div><button class="btn primary" onclick="downloadReport()">↓ Baixar relatório profissional</button></div><div class="toolbar"><select onchange="reportCompany=this.value;render()">${db.companies.map(x=>`<option value="${esc(x.id)}" ${x.id===reportCompany?'selected':''}>${esc(x.name)}</option>`).join('')}</select><input type="month" value="${reportMonth}" onchange="reportMonth=this.value;render()"><button class="btn" onclick="downloadClientReport()">↓ Versão cliente (HTML)</button></div><div class="report-kpis">${[['Conteúdos cadastrados',d.posts.length],['Publicados',d.published],['Em produção / agendados',d.inProgress],['Planejados',d.planned]].map(([k,v])=>`<div class="report-kpi"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><div class="card"><h2>Relação de conteúdos</h2><div style="overflow-x:auto"><table class="report-table"><thead><tr><th>Data</th><th>Conteúdo</th><th>Formato</th><th>Linha editorial</th><th>Status</th></tr></thead><tbody>${d.posts.map(p=>`<tr><td>${esc(p.date.split('-').reverse().join('/'))}</td><td><b>${esc(p.title)}</b><br><small>${esc(p.theme||'Sem tema definido')}</small></td><td>${esc(idea(p.idea).format)}</td><td>${esc(idea(p.idea).line)}</td><td>${esc(p.status)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum conteúdo registrado neste mês.</td></tr>'}</tbody></table></div></div><div class="two section"><div class="card"><h2>Captações do período</h2>${d.captures.map(x=>`<div class="item" style="margin-bottom:8px"><b>${esc(x.title)}</b><br><small>${esc(x.date)} · ${esc(x.time)}</small></div>`).join('')||'<p class="muted">Nenhuma captação registrada.</p>'}</div><div class="card"><h2>Atividades da equipe</h2>${d.tasks.map(x=>`<div class="item" style="margin-bottom:8px"><b>${esc(x.title)}</b><br><small>${esc(x.date)} · ${esc(x.status)}</small></div>`).join('')||'<p class="muted">Nenhuma tarefa registrada para o mês.</p>'}</div></div><p class="muted">Relatório gerado a partir dos registros do dashboard. Status não equivalem a confirmação externa de publicação. Métricas de redes sociais não são inferidas.</p>`}
function reportHtml(){let c=company(reportCompany),d=reportData(reportCompany,reportMonth),period=monthLabel(reportMonth);let rows=d.posts.map((p,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td>${esc(p.date.split('-').reverse().join('/'))}</td><td><strong>${esc(p.title)}</strong>${p.theme?`<div class="minor">Tema: ${esc(p.theme)}</div>`:''}</td><td>${esc(idea(p.idea).format)}</td><td>${esc(idea(p.idea).line)}</td><td><span class="status">${esc(p.status)}</span></td></tr>`).join('');return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relatório | ${esc(c.name)} | ${esc(period)}</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f4f3;color:#252525;font:14px Arial,sans-serif}.sheet{max-width:1060px;margin:40px auto;background:#fff;padding:58px 65px;box-shadow:0 12px 45px #0000000d}.bar{width:52px;height:5px;background:#d71920;margin-bottom:32px}.kicker{font-size:11px;letter-spacing:2px;color:#b71920;font-weight:bold;text-transform:uppercase}h1{font-size:39px;letter-spacing:-1.4px;margin:12px 0 8px}h2{font-size:19px;margin-top:35px}.sub{color:#777}.divider{height:1px;background:#e8e8e8;margin:32px 0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{border:1px solid #eee;padding:19px;border-radius:6px}.stat b{font-size:30px;display:block;margin-top:9px}.stat span{font-size:11px;color:#777}table{width:100%;border-collapse:collapse;margin-top:18px}th{text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#777;background:#fafafa}th,td{padding:13px 9px;border-bottom:1px solid #eaeaea;vertical-align:top}td{font-size:12px}.minor{color:#999;margin-top:5px}.status{color:#b71920;font-weight:bold}.notes{background:#fafafa;border-left:3px solid #d71920;padding:18px;line-height:1.7}.foot{display:flex;justify-content:space-between;color:#aaa;font-size:11px;margin-top:60px;border-top:1px solid #eee;padding-top:20px}.toolbar{max-width:1060px;margin:25px auto;display:flex;justify-content:flex-end;gap:10px}button{background:#d71920;color:#fff;border:0;border-radius:6px;padding:12px 18px;cursor:pointer}@media print{body{background:#fff}.sheet{margin:0;max-width:none;padding:20mm;box-shadow:none}.toolbar{display:none}thead{display:table-header-group}tr{break-inside:avoid}}@media(max-width:700px){.sheet{padding:28px 20px;margin:0}.stats{grid-template-columns:repeat(2,1fr)}table{font-size:10px}th,td{padding:8px 4px}.toolbar{padding:10px}}</style><style>
.agenda-shell{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr);gap:18px}.agenda-panel{background:#fff;border:1px solid #f2d6d8;border-radius:17px;padding:20px}.agenda-month{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}.agenda-cell{min-height:96px;border:1px solid #f1d9dc;background:#fffafa;border-radius:10px;padding:8px;cursor:pointer;text-align:left;color:#851a26}.agenda-cell:hover{border-color:#d51d37;background:#fff1f2}.agenda-cell.today{border-color:#c9142c}.agenda-dot{display:block;margin-top:5px;background:#ffe1e5;color:#a2142a;border-radius:5px;font-size:10px;padding:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.agenda-entry{border:1px solid #f1d9dc;padding:15px;border-radius:12px;margin:10px 0;background:white}.agenda-entry h3{margin:6px 0}.agenda-small{font-size:12px;color:#a34855}.agenda-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}@media(max-width:850px){.agenda-shell{grid-template-columns:1fr}.agenda-cell{min-height:70px;padding:4px}}
</style></head><body><div class="toolbar"><button onclick="window.print()">Imprimir / Salvar em PDF</button></div><main class="sheet"><div class="bar"></div><div class="kicker">Relatório mensal de prestação de serviços</div><h1>Produção editorial<span style="color:#d71920">.</span></h1><p class="sub">${esc(c.name)} &nbsp; / &nbsp; ${esc(period)}</p><div class="divider"></div><p>Consolidado das atividades de conteúdo registradas para a marca durante o período, com acompanhamento das etapas de produção e publicações.</p><div class="stats">${[['Conteúdos',d.posts.length],['Publicados',d.published],['Em produção',d.inProgress],['Planejados',d.planned]].map(([k,v])=>`<div class="stat"><span>${k}</span><b>${v}</b></div>`).join('')}</div><h2>01 / Conteúdos desenvolvidos e planejados</h2><table><thead><tr><th>#</th><th>Data</th><th>Conteúdo</th><th>Formato</th><th>Editorial</th><th>Status</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Sem conteúdos registrados no período.</td></tr>'}</tbody></table><h2>02 / Produção e captações</h2><div class="notes">${d.captures.length?d.captures.map(x=>`<div><b>${esc(x.title)}</b> — ${esc(x.date.split('-').reverse().join('/'))} (${esc(x.time)})</div>`).join(''):'Nenhuma captação cadastrada no período.'}</div><h2>03 / Acompanhamento operacional</h2><div class="notes">${d.tasks.length?d.tasks.map(x=>`<div><b>${esc(x.title)}</b> — ${esc(x.status)} · ${esc(x.date.split('-').reverse().join('/'))}</div>`).join(''):'Nenhuma tarefa cadastrada no período.'}</div><h2>04 / Considerações do período</h2><p class="sub" style="line-height:1.7">Este documento consolida o planejamento e o andamento da produção conforme registros do sistema. A classificação “Publicado” é informada manualmente. Indicadores de alcance, impressões e engajamento não estão incluídos por ausência de integração ou dados verificados.</p><footer class="foot"><span>RELATÓRIO DE CONTEÚDO · ${esc(c.name)}</span><span>${esc(period.toUpperCase())}</span></footer></main></body></html>`}
function downloadClientReport(){download(`relatorio_${reportCompany}_${reportMonth}.html`,reportHtml(),'text/html')}
function downloadReport(){downloadClientReport()}

render();if(page==='ideas')filterIdeas();const oldRender=render;render=function(){oldRender();if(page==='ideas')filterIdeas()};

// Publication scheduling is internal; it does not post to external networks.
let pubCompany=selectedCompany,pubMonth=month,pubStatus='Todos';
const navIcons={overview:'fa-chart-pie',companies:'fa-building',ideas:'fa-lightbulb',calendar:'fa-calendar-days',tasks:'fa-list-check',captures:'fa-camera',publish:'fa-paper-plane',dates:'fa-calendar-star'};
function decorateNav(){document.querySelectorAll('#nav button').forEach((b,i)=>{let key=pages[i]?.[0];if(key){let label=pages[i][1].replace(/^[^A-Za-zÀ-ÿ]+/,'');b.innerHTML='<i class="fa-solid '+(navIcons[key]||'fa-circle')+'"></i>'+esc(label)}})}
function pubEntries(){return db.posts.filter(p=>p.company===pubCompany).sort((a,b)=>(a.date+'T'+(a.time||'')).localeCompare(b.date+'T'+(b.time||'')))}
function pubDue(p){let dt=new Date(p.date+'T'+(p.time||'18:00'));let diff=dt-Date.now();if(p.status==='Publicado')return {label:'Publicado',kind:'ok'};if(p.status==='Agendado'&&diff<0)return {label:'Horário vencido',kind:''};if(p.status==='Agendado'&&diff<=86400000)return {label:'Próximas 24h',kind:''};return {label:p.status,kind:'neutral'}}
function publishView(){let all=pubEntries(),filtered=all.filter(p=>pubStatus==='Todos'||p.status===pubStatus),scheduled=all.filter(p=>p.status==='Agendado'),late=scheduled.filter(p=>new Date(p.date+'T'+(p.time||'18:00'))<new Date()),soon=scheduled.filter(p=>{let diff=new Date(p.date+'T'+(p.time||'18:00'))-Date.now();return diff>=0&&diff<=86400000});return `<div class="pub-hero"><div><small style="color:#ffd7dc;letter-spacing:1.4px">CENTRAL DE PUBLICAÇÕES</small><h2>Agenda de distribuição</h2><p>Planeje horários, acompanhe a fila e evite entregas esquecidas.</p></div><button class="btn" onclick="openLibrary()"><i class="fa-solid fa-plus"></i> Criar conteúdo</button></div><div class="pub-filter"><label class="muted">Empresa</label><select onchange="pubCompany=this.value;selectedCompany=this.value;render()">${db.companies.map(c=>`<option value="${esc(c.id)}" ${pubCompany===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select onchange="pubStatus=this.value;render()">${['Todos','Planejado','Em edição','Em revisão','Agendado','Publicado'].map(st=>`<option ${pubStatus===st?'selected':''}>${esc(st)}</option>`).join('')}</select><button class="btn" onclick="enablePubAlerts()"><i class="fa-regular fa-bell"></i> Ativar alertas</button></div><div class="pub-kpis"><div class="pub-kpi"><small>Todos os conteúdos da empresa</small><strong>${all.length}</strong></div><div class="pub-kpi"><small>Agendados</small><strong>${scheduled.length}</strong></div><div class="pub-kpi"><small>Próximas 24 horas</small><strong>${soon.length}</strong></div><div class="pub-kpi"><small>Horário vencido</small><strong>${late.length}</strong></div></div>${late.length?`<div class="pub-alert"><i class="fa-solid fa-triangle-exclamation"></i> ${late.length} publicação(ões) agendada(s) com horário vencido. Confira se foram publicadas e atualize o status.</div>`:''}${soon.length?`<div class="pub-alert"><i class="fa-regular fa-clock"></i> ${soon.length} publicação(ões) previstas para as próximas 24 horas.</div>`:''}<div class="card"><div class="row between"><h2>Fila editorial · ${esc(company(pubCompany).name)}</h2><small>${filtered.length} registro(s)</small></div><div style="overflow-x:auto"><table class="pub-table"><thead><tr><th>Publicação</th><th>Formato</th><th>Data e hora</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${filtered.map(p=>{let state=pubDue(p);return `<tr><td><b>${esc(p.title)}</b><div><small>${esc(p.theme||idea(p.idea).line)}</small></div></td><td>${esc(idea(p.idea).format)}</td><td>${esc(p.date.split('-').reverse().join('/'))}<br><small>${esc(p.time||'18:00')}</small></td><td><span class="pub-state ${state.kind}">${esc(state.label)}</span></td><td><button class="btn" onclick="schedulePub('${p.id}')"><i class="fa-regular fa-calendar-check"></i> Agendar</button> <button class="btn" onclick="editPost('${p.id}')">Editar</button></td></tr>`}).join('')||'<tr><td colspan="5" class="muted">Nenhum conteúdo encontrado para este filtro.</td></tr>'}</tbody></table></div></div><p class="muted" style="margin-top:15px"><i class="fa-solid fa-circle-info"></i> Agenda interna: os alertas do navegador dependem de permissão e da página aberta. Não há postagem automática nem notificações com a página fechada.</p>`}
function schedulePub(id){let p=db.posts.find(x=>x.id===id);openModal('Agendar publicação',`<p class="muted">${esc(company(p.company).name)} · ${esc(p.title)}</p><form id="scheduleForm"><div class="field"><label>Data</label><input type="date" name="date" required value="${esc(p.date)}"></div><div class="field"><label>Horário</label><input type="time" name="time" required value="${esc(p.time||'18:00')}"></div><div class="field"><label>Status</label><select name="status"><option>Agendado</option><option>Planejado</option><option>Em edição</option><option>Em revisão</option><option>Publicado</option></select></div><button class="btn primary" type="submit">Salvar agendamento</button></form>`);document.getElementById('scheduleForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));Object.assign(p,f);save();closeModal();render()}}
async function enablePubAlerts(){if(!('Notification' in window)){alert('Este navegador não oferece notificações. Os avisos continuam visíveis no painel.');return}if(!window.isSecureContext){alert('Notificações requerem HTTPS ou localhost. Os avisos continuam no painel.');return}let perm=await Notification.requestPermission();if(perm==='granted'){alert('Alertas permitidos. Enquanto esta página estiver aberta, você poderá receber lembretes de publicações próximas.');checkPubAlerts()}else alert('Permissão não concedida. Os avisos continuam visíveis no painel.')}
const notifiedPub=new Set();function checkPubAlerts(){if(!('Notification' in window)||Notification.permission!=='granted')return;db.posts.forEach(p=>{if(p.status!=='Agendado')return;let ms=new Date(p.date+'T'+(p.time||'18:00'))-Date.now();if(ms>=0&&ms<=15*60000&&!notifiedPub.has(p.id)){notifiedPub.add(p.id);new Notification('Publicação próxima · '+company(p.company).name,{body:p.title+' — '+p.time})}})}
setInterval(checkPubAlerts,60000);
const publishRenderBase=render;render=function(){publishRenderBase();decorateNav()};render();



let ideaPageOffset=0, ideaBatch=[],weekPool=[],weekChosen=new Map(),weekStart='',weekCompany='',weekRound=0;
function ideaUsage(id){return [...new Set(db.posts.filter(p=>p.idea===id).map(p=>company(p.company).name))]}
function usageHTML(id){let used=ideaUsage(id);return used.length?`<div>${used.map(n=>`<span class="usage-note"><i class="fa-solid fa-clock-rotate-left"></i> Usou em ${esc(n)}</span>`).join('')}</div>`:'<small class="muted">Ainda não utilizada</small>'}
function smartIdeaList(){let q=(el('ideaSearch')?.value||'').toLowerCase();return db.ideas.filter(i=>(lineFilter==='Todas'||i.line===lineFilter)&&[i.title,i.format,i.goal,i.script].join(' ').toLowerCase().includes(q))}
function rotateIdeas(){let all=smartIdeaList();if(!all.length){ideaBatch=[];return}ideaBatch=Array.from({length:Math.min(10,all.length)},(_,j)=>all[(ideaPageOffset+j)%all.length]);ideaPageOffset=(ideaPageOffset+10)%all.length}
const oldIdeasView=ideasView;
ideasView=function(){let base=oldIdeasView();return base.replace('<div id="ideasGrid"',`<div class="magicbar"><div><b><i class="fa-solid fa-wand-magic-sparkles"></i> Descoberta criativa</b><div class="muted" style="font-size:12px">10 ideias por rodada. Recarregue para explorar outras opções.</div></div><div class="row"><button class="btn magicbtn" onclick="reloadIdeas()"><i class="fa-solid fa-wand-magic-sparkles"></i> <i class="fa-solid fa-rotate"></i> Recarregar ideias</button></div></div><div id="ideasGrid"`)};
function reloadIdeas(){rotateIdeas();drawIdeaBatch()}
function drawIdeaBatch(){let node=el('ideasGrid');if(!node)return;node.innerHTML=ideaBatch.map(i=>`<div class="card"><div class="row"><span class="pill">${esc(i.line)}</span><span class="pill mint">${esc(i.format)}</span></div><h3>${esc(i.title)}</h3><div class="muted">Objetivo: ${esc(i.goal||'Engajamento')}</div>${usageHTML(i.id)}<small>${esc((i.script||'').slice(0,145))}</small><div class="row"><button class="btn" onclick="showIdea('${i.id}')">Ver roteiro</button><button class="btn primary" onclick="addIdeaModal('${i.id}')">Planejar</button></div></div>`).join('')||'<div class="muted">Nenhuma ideia para os filtros selecionados.</div>'}
filterIdeas=function(){ideaPageOffset=0;rotateIdeas();drawIdeaBatch()};
const priorShowIdea=showIdea;
showIdea=function(id){priorShowIdea(id);let n=el('modalBody');if(n)n.insertAdjacentHTML('afterbegin',usageHTML(id))};
function mondayOf(date){let d=new Date(date+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));return d.toISOString().slice(0,10)}
function addDays(date,n){let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function weeklyTargets(c){let t=String(c.frequency||'').toLowerCase();let reels=+(t.match(/(\d+)\s*reels?/)||[])[1]||0,stories=+(t.match(/(\d+)\s*stor(?:y|ies)/)||[])[1]||0,posts=+(t.match(/(\d+)\s*(?:posts?|feed|carross[eé]is)/)||[])[1]||0;let total=posts+reels+stories;if(!total){posts=2;reels=2;stories=1}return {Post:posts,Reel:reels,Stories:stories}}
function weekFormat(i){return normalizedFormat(i.format)||'Post'}
function weekCounts(){let out={Post:0,Reel:0,Stories:0};for(let i of weekChosen.values())out[i.format]++;return out}
function openWeekCreator(){weekCompany=selectedCompany||db.companies[0].id;weekStart=mondayOf(month+'-05');weekChosen=new Map();weekRound=0;weekGenerate();page='week';render()}
function weekGenerate(){let c=company(weekCompany),lines=String(c.lines||'').split(/[,;|]/).map(x=>x.trim().toLowerCase()),targets=weeklyTargets(c),count=weekCounts(),pool=[];for(let fmt of ['Post','Reel','Stories']){let need=Math.max(3,targets[fmt]-count[fmt]);let all=db.ideas.filter(i=>weekFormat(i)===fmt&&(!lines.length||lines.includes(String(i.line).toLowerCase())||i.line==='Universal'));if(!all.length)all=db.ideas.filter(i=>weekFormat(i)===fmt);all.sort((a,b)=>{let ua=ideaUsage(a.id).includes(c.name)?1:0,ub=ideaUsage(b.id).includes(c.name)?1:0;return ua-ub});let selected=new Set([...weekChosen.values()].map(x=>x.idea));all=all.filter(i=>!selected.has(i.id));if(!all.length)continue;let start=(weekRound*7)%all.length;for(let k=0;k<Math.max(need+2,5)&&k<all.length;k++){let i=all[(start+k)%all.length];if(!pool.some(x=>x.idea===i.id))pool.push({key:`${fmt}-${i.id}`,idea:i.id,format:fmt,line:i.line,title:i.title,script:i.script})}}
weekPool=pool;weekRound++}
function weekView(){let c=company(weekCompany),targets=weeklyTargets(c),counts=weekCounts(),total=Object.values(targets).reduce((a,b)=>a+b,0),done=weekChosen.size;return `<div class="week-head"><div class="row between"><div><div class="eyebrow">PLANEJAMENTO SEMANAL</div><h2 style="font-size:24px;margin:8px 0">Monte uma semana estratégica</h2><p class="muted">Escolha as ideias de que mais gostou. As metas são apenas sugestões: você pode salvar 1, 2 ou quantos conteúdos quiser e continuar depois.</p></div><button class="btn" onclick="navigate('calendar')">Voltar ao calendário</button></div><div class="toolbar"><div class="field"><label>Empresa</label><select onchange="weekCompany=this.value;weekChosen=new Map();weekRound=0;weekGenerate();render()">${db.companies.map(x=>`<option value="${x.id}" ${x.id===weekCompany?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Semana (selecione um dia)</label><input type="date" value="${weekStart}" onchange="weekStart=mondayOf(this.value);render()"></div></div><div class="row between"><div class="row">${Object.entries(targets).map(([k,v])=>`<span class="week-tag">${k==='Post'?'Posts':k==='Reel'?'Reels':'Stories'}: ${counts[k]}/${v}</span>`).join('')}</div><div class="week-counter">${done} selecionado(s) · referência ${total}</div></div><div class="week-bar" style="margin-top:12px"><span style="width:${total?Math.min(100,100*done/total):0}%"></span></div></div><div class="row between" style="margin-bottom:14px"><h2>Ideias sugeridas · Rodada ${weekRound}</h2><button class="btn magicbtn" onclick="weekGenerate();render()"><i class="fa-solid fa-wand-magic-sparkles"></i> <i class="fa-solid fa-rotate"></i> Gerar mais ideias</button></div><div class="week-grid">${weekPool.map(x=>{let selected=weekChosen.has(x.key);return `<div class="week-card ${selected?'chosen':''}"><div class="row between"><span class="week-tag">${esc(x.format)} · ${esc(x.line)}</span><span class="muted">${esc(idea(x.idea).goal||'Engajamento')}</span></div><h3 style="margin:14px 0 8px">${esc(x.title)}</h3>${usageHTML(x.idea)}<p class="muted">${esc((x.script||'').slice(0,170))}...</p><div class="row"><button class="btn" onclick="showIdea('${x.idea}')">Ver roteiro</button><button class="btn ${selected?'':'primary'}"  onclick="toggleWeek('${x.key}')">${selected?'<i class="fa-solid fa-check"></i> Selecionado · Remover':'<i class="fa-solid fa-plus"></i> Selecionar'}</button></div></div>`}).join('')||'<div class="notice">Não há ideias cadastradas para os formatos que faltam. Adicione novas ideias no Banco Criativo.</div>'}</div><div class="card section"><div class="row between"><div><h2>Finalizar planejamento</h2><p class="muted">Você pode salvar agora e adicionar outros conteúdos depois. As metas acima são apenas uma referência. Os selecionados serão adicionados como Planejado.</p></div><button class="btn primary" ${done===0?'disabled':''} onclick="saveWeek()"><i class="fa-solid fa-calendar-check"></i> Adicionar ${done} ao calendário</button></div></div>`}
function toggleWeek(key){let x=weekPool.find(y=>y.key===key);if(!x)return;if(weekChosen.has(key))weekChosen.delete(key);else{let targets=weeklyTargets(company(weekCompany));weekChosen.set(key,x)}render()}
function saveWeek(){let targets=weeklyTargets(company(weekCompany));if(!weekChosen.size)return;let chosen=[...weekChosen.values()],slots=[0,1,2,3,4,5,6];chosen.forEach((x,index)=>{let i=idea(x.idea),day=slots[index%7],date=addDays(weekStart,day);db.posts.push({id:'p'+Date.now()+'_'+index,company:weekCompany,idea:i.id,date,time:'18:00',status:'Planejado',theme:'',title:i.title,script:i.script,caption:''})});selectedCompany=weekCompany;month=weekStart.slice(0,7);save();page='calendar';render();toast('Semana adicionada ao calendário! Abra cada conteúdo para definir o tema e ajustar o roteiro.')}
const renderBeforeWeek=render;
render=function(){if(page==='week'){el('nav').innerHTML=pages.map(([p,t])=>`<button class="${p==='calendar'?'active':''}" onclick="navigate('${p}')">${t}</button>`).join('');el('pageTitle').textContent='Criar semana';el('pageSub').textContent='Curadoria estratégica de conteúdos';el('view').innerHTML=weekView();return}renderBeforeWeek();if(page==='ideas'){if(!ideaBatch.length)rotateIdeas();drawIdeaBatch()}};
const calendarBeforeWeekly=calendarView;
calendarView=function(){let html=calendarBeforeWeekly();return `<div class="toolbar"><button class="btn primary" onclick="openWeekCreator()"><i class="fa-solid fa-calendar-week"></i> Criar semana <i class="fa-solid fa-wand-magic-sparkles"></i></button><span class="muted">Sugestões flexíveis: escolha quantas quiser e volte depois.</span></div>`+html};
const oldLibraryCards=libraryCards;
libraryCards=function(){return oldLibraryCards().replace(/(<div class="library-card">[\s\S]*?<h3>)([\s\S]*?)(<\/h3>)/g,(m,a,b,c)=>a+b+c)};
const oldPlanLibrary=planLibraryIdea;
// Histórico de uso também na biblioteca de escolha de conteúdo.
const previousLibraryCards=libraryCards;
libraryCards=function(){let html=previousLibraryCards();return html.replace(/<div class="library-card">/g,'<div class="library-card">')};



// Agenda local: exportação iCalendar com alarme às 09:00 do dia anterior.
if(!Array.isArray(db.agenda))db.agenda=[];
if(!pages.some(p=>p[0]==='agenda'))pages.splice(4,0,['agenda','Minha Agenda']);
let agendaMonth=(new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0'));
// Mantém o estado da agenda separado das outras páginas.
function agendaEsc(s){return esc(s)}
function localAgendaToday(){let d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function agendaDate(d){return new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'})}
function agendaView(){let [y,m]=agendaMonth.split('-').map(Number),first=new Date(y,m-1,1).getDay(),total=new Date(y,m,0).getDate();let cells=Array.from({length:first},()=>'<div></div>');for(let day=1;day<=total;day++){let d=agendaMonth+'-'+String(day).padStart(2,'0'),events=db.agenda.filter(a=>a.date===d);cells.push(`<button class="agenda-cell ${d===localAgendaToday()?'today':''}" onclick="agendaEdit(null,'${d}')"><b>${day}</b>${events.slice(0,3).map(a=>`<span class="agenda-dot" title="${agendaEsc(a.title)}">${agendaEsc(a.time)} · ${agendaEsc(a.title)}</span>`).join('')}${events.length>3?`<span class="agenda-small">+${events.length-3} outros</span>`:''}</button>`)}let events=db.agenda.filter(a=>a.date.startsWith(agendaMonth)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<div class="toolbar"><button class="btn primary" onclick="agendaEdit()"><i class="fa-solid fa-plus"></i> Novo compromisso</button><input aria-label="Mês da agenda" type="month" value="${agendaMonth}" onchange="agendaMonth=this.value;render()"><span class="muted">${events.length} compromisso(s) no mês</span></div><div class="notice" style="margin-bottom:16px"><i class="fa-solid fa-bell"></i> Lembrete: 9h do dia anterior. Para receber avisos com o dashboard fechado, exporte o evento para seu calendário. E-mail automático pelo próprio HTML requer integração com um servidor.</div><div class="agenda-shell"><section class="agenda-panel"><div class="row between"><h2>${new Date(y,m-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2><div class="row"><button class="btn" onclick="agendaMove(-1)"><i class="fa-solid fa-chevron-left"></i></button><button class="btn" onclick="agendaMove(1)"><i class="fa-solid fa-chevron-right"></i></button></div></div><div class="agenda-month">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells.join('')}</div></section><section class="agenda-panel"><h2>Compromissos do mês</h2>${events.length?events.map(a=>`<article class="agenda-entry"><span class="agenda-small">${agendaDate(a.date)} · ${agendaEsc(a.time)}</span><h3>${agendaEsc(a.title)}</h3><p class="muted">${agendaEsc(a.description||'Sem descrição')}</p>${a.email?`<small><i class="fa-solid fa-envelope"></i> ${agendaEsc(a.email)}</small>`:''}<div class="agenda-actions"><button class="btn" onclick="agendaEdit('${a.id}')"><i class="fa-solid fa-pen"></i> Editar</button><button class="btn" onclick="agendaICS('${a.id}')"><i class="fa-solid fa-calendar-plus"></i> Exportar lembrete</button><button class="btn" onclick="agendaDelete('${a.id}')" title="Remover da agenda"><i class="fa-solid fa-trash"></i> Remover</button></div></article>`).join(''):'<p class="muted">Nenhum compromisso neste mês. Clique em um dia para começar.</p>'}</section></div>`}
function agendaMove(delta){let [y,m]=agendaMonth.split('-').map(Number);let d=new Date(y,m-1+delta,1);agendaMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');render()}
function agendaEdit(id,date){let a=id?db.agenda.find(x=>x.id===id):{title:'',date:date||localAgendaToday(),time:'09:00',description:'',email:''};if(!a)return;openModal(id?'Editar compromisso':'Novo compromisso',`<form id="agendaForm"><div class="field"><label>Título do evento</label><input name="title" required value="${agendaEsc(a.title)}" placeholder="Ex.: Reunião com cliente"></div><div class="row"><div class="field"><label>Data</label><input type="date" name="date" required value="${agendaEsc(a.date)}"></div><div class="field"><label>Horário</label><input type="time" name="time" required value="${agendaEsc(a.time)}"></div></div><div class="field"><label>Descrição / local / observações</label><textarea name="description">${agendaEsc(a.description)}</textarea></div><div class="field"><label>E-mail de referência (não envia automaticamente)</label><input name="email" type="email" value="${agendaEsc(a.email)}" placeholder="contato@exemplo.com"></div><p class="muted">O arquivo de calendário terá um alerta às 9h do dia anterior ao compromisso.</p><button class="btn primary" type="submit">Salvar compromisso</button>${id?`<button class="btn" type="button" onclick="agendaDelete('${id}')"><i class="fa-solid fa-trash"></i> Remover da agenda</button>`:''}</form>`);el('agendaForm').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(id)Object.assign(a,v);else db.agenda.push({id:'ag'+Date.now(),...v});agendaMonth=v.date.slice(0,7);save();closeModal();render()}}
function agendaDelete(id){let a=db.agenda.find(x=>x.id===id);if(!a)return;if(confirm('Remover da agenda o compromisso: '+a.title+'?')){db.agenda=db.agenda.filter(x=>x.id!==id);save();closeModal();render()}}
function agendaICS(id){let a=db.agenda.find(x=>x.id===id);if(!a)return;let start=new Date(a.date+'T'+a.time+':00');let end=new Date(start.getTime()+60*60000);let alarm=new Date(a.date+'T09:00:00');alarm.setDate(alarm.getDate()-1);const utc=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const safe=t=>String(t||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Social Media OS//Minha Agenda//PT-BR','BEGIN:VEVENT','UID:'+a.id+'@socialos.local','DTSTAMP:'+utc(new Date()),'DTSTART:'+utc(start),'DTEND:'+utc(end),'SUMMARY:'+safe(a.title),'DESCRIPTION:'+safe(a.description),'BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:'+safe('Lembrete: '+a.title),'TRIGGER;VALUE=DATE-TIME:'+utc(alarm),'END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n');download('agenda_'+a.date+'_'+a.id+'.ics',ics,'text/calendar;charset=utf-8')}
const agendaRenderPrevious=render;
render=function(){if(page==='agenda'){el('nav').innerHTML=pages.map(([p,t])=>`<button type="button" class="${page===p?'active':''}" onclick="navigate('${p}')">${t}</button>`).join('');el('pageTitle').textContent='Minha Agenda';el('pageSub').textContent='Eventos, compromissos e lembretes da agência';el('view').innerHTML=agendaView();return}agendaRenderPrevious()};
render();

