const socialNavIcons={overview:'fa-chart-pie',companies:'fa-building',ideas:'fa-wand-magic-sparkles',calendar:'fa-calendar-days',agenda:'fa-calendar-check',tasks:'fa-list-check',captures:'fa-camera',publish:'fa-paper-plane',dates:'fa-star',reports:'fa-file-lines'};
const socialRenderOriginal=render;
render=function(){socialRenderOriginal();let nav=document.getElementById('nav');if(nav){nav.innerHTML=pages.map(([key])=>`<button type="button" class="${page===key?'active':''}" onclick="navigate('${key}')"><i class="fa-solid ${socialNavIcons[key]||'fa-circle'}" aria-hidden="true"></i><span>${(key==='finance'?'Pagamentos':socialNavLabels[key]||key)}</span></button>`).join('')}};
