const MAX_LOGO_URL='https://i.ibb.co/3YL1TFBX/CRACH-S-DA-MAX-2.png';
function maxDocumentBrand(html,kind){
 const header='<div class="max-export-brand"><img src="'+MAX_LOGO_URL+'" alt="MAX AGÊNCIA"><div>MAX AGÊNCIA - ASSESSORIA DE MARKETING<small>'+kind+'</small></div></div>';
 const style='<style>.max-export-brand{background:#c80203;color:#fff;padding:22px 26px;border-radius:10px;display:flex;align-items:center;gap:22px;margin:0 0 28px;break-inside:avoid}.max-export-brand img{width:145px;max-height:95px;object-fit:contain}.max-export-brand div{font:700 16px Arial,sans-serif;letter-spacing:.3px}.max-export-brand small{display:block;font:400 11px Arial,sans-serif;margin-top:7px;letter-spacing:1.5px}@media print{.max-export-brand{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style>';
 return html.replace('</head>',style+'</head>').replace(/(<body[^>]*>)/i,'$1'+header).replace(/(<html[^>]*>)/i,'$1');
}
