 // A planilha é a fonte de verdade. Não publicar dados de demonstração na carga inicial.
 mark('Conectando ao Google Sheets…');setTimeout(()=>refresh(true),100);
 setInterval(()=>{if(document.hidden)return;if(operations().length)flush();else refresh()},12000);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)window.maxSyncNow()});
 window.addEventListener('online',()=>window.maxSyncNow());
