/* Exclusão de empresa e novo visual do HTML entregue ao cliente */
function deleteCompany(id){
 const c=db.companies.find(x=>String(x.id)===String(id));if(!c)return;
 const keys=['posts','tasks','captures','finance','agenda'];
 const summary=keys.map(k=>`${(db[k]||[]).filter(x=>String(x.company)===String(id)).length} ${k}`).join(', ');
 if(!confirm(`Apagar ${c.name}? Também serão excluídos registros vinculados: ${summary}. A exclusão será sincronizada com o Sheets e não poderá ser desfeita.`))return;
 if(prompt('Digite EXCLUIR para confirmar a remoção permanente:')!=='EXCLUIR')return;
 db.companies=db.companies.filter(x=>String(x.id)!==String(id));
 keys.forEach(k=>{if(Array.isArray(db[k]))db[k]=db[k].filter(x=>String(x.company)!==String(id))});
 if(selectedCompany===id)selectedCompany=db.companies[0]?.id||'';
 if(typeof reportCompany!=='undefined'&&reportCompany===id)reportCompany=db.companies[0]?.id||'';
 save();closeModal();render();
}
