let maxDraggedTask=null;
function maxTaskDragStart(event,id){maxDraggedTask=id;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',id);event.currentTarget.classList.add('max-dragging')}
function maxTaskDragEnd(event){event.currentTarget.classList.remove('max-dragging');document.querySelectorAll('.max-drop-active').forEach(x=>x.classList.remove('max-drop-active'));maxDraggedTask=null}
function maxTaskDragOver(event){event.preventDefault();event.dataTransfer.dropEffect='move';event.currentTarget.classList.add('max-drop-active')}
function maxTaskDragLeave(event){if(!event.currentTarget.contains(event.relatedTarget))event.currentTarget.classList.remove('max-drop-active')}
function maxTaskDrop(event,status){event.preventDefault();event.currentTarget.classList.remove('max-drop-active');const id=event.dataTransfer.getData('text/plain')||maxDraggedTask;const task=db.tasks.find(t=>String(t.id)===String(id));if(task&&['A fazer','Em andamento','Revisão','Concluído'].includes(status)&&task.status!==status){task.status=status;save();render()}maxDraggedTask=null}
function tasksView(){const stages=['A fazer','Em andamento','Revisão','Concluído'];return `<div class="toolbar"><button class="btn primary" onclick="taskModal()">＋ Nova tarefa</button><span class="muted">Arraste os cartões entre as etapas para atualizar o status.</span></div><div class="kanban max-kanban">${stages.map((s,i)=>`<section class="card max-kanban-column" ondragover="maxTaskDragOver(event)" ondragleave="maxTaskDragLeave(event)" ondrop="maxTaskDrop(event,${JSON.stringify(s).replace(/"/g,'&quot;')})"><div class="row between max-kanban-head"><h3><span class="max-stage-dot max-stage-${i}"></span>${s}</h3><span class="pill">${db.tasks.filter(t=>t.status===s).length}</span></div><div class="max-kanban-items">${db.tasks.filter(t=>t.status===s).map(t=>`<article class="item max-task-card" draggable="true" ondragstart="maxTaskDragStart(event,${JSON.stringify(String(t.id)).replace(/"/g,'&quot;')})" ondragend="maxTaskDragEnd(event)"><div class="max-drag-handle">⠿ Arraste para mover</div><strong>${esc(t.title)}</strong><small>${esc(company(t.company).name)} · ${esc(t.date||'Sem prazo')}</small><div class="row max-task-actions"><button class="btn" onclick="taskModal('${esc(t.id)}')">Editar</button><button class="btn" onclick="maxDeleteRecord('tasks','${esc(t.id)}')">Excluir</button></div></article>`).join('')||'<div class="max-empty-stage">Solte uma tarefa aqui</div>'}</div></section>`).join('')}</div>`}
